final class MewEventDataCoreTest { static void run(){ var i=MewEventDataCore.build(RomProfile.FIRE_RED_EN_10); require(i.bytes().length<=MewEventDataCore.CAPACITY,"Module B must fit SB1 tail"); require((i.bytes().length&3)==0,"Module B aligned"); require(i.rewardOffset()>=MewEventDataCore.HEADER_SIZE,"reward entry"); require(i.ensureMewOffset()>i.rewardOffset(),"ensure after reward"); require(i.transformRebindOffset()>i.ensureMewOffset(),"transform after ensure"); } private static void require(boolean x,String m){if(!x)throw new AssertionError(m);} }
